+// Stock de un artículo en cada almacén donde tuvo movimientos, ordenado por código de almacén.
+export function stockPorAlmacen(movimientos, articulo) {
+  const almacenes = [...new Set(movimientos.filter((m) => m.articulo === articulo).map((m) => m.almacen))];
+  return almacenes
+    .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
+    .map((almacen) => ({ almacen, stock: stock(movimientos, articulo, almacen) }));
+}
